from typing import List
class Solution:
    def jump(self, nums: List[int]) -> int:
        n = len(nums)
        INF = 10**9
        dp = [INF] * n
        dp[0] = 0
        for i in range(1, n):
            for j in range(i):
                if j + nums[j] >= i:
                    if dp[j] + 1 < dp[i]:
                        dp[i] = dp[j] + 1
        return dp[n-1]

