        vector<char> vis(n, 0);
        vis[0] = 1;
        queue<int> q;
        q.push(0);
        int jumps = 0;
        while (!q.empty()) {
            ++jumps;
            int sz = q.size();
            while (sz--) {
                int cur = q.front(); q.pop();
                int reach = min(n - 1, cur + nums[cur]);
                for (int nxt = cur + 1; nxt <= reach; ++nxt) {
                    if (nxt == n - 1) return jumps;
                    if (!vis[nxt]) { vis[nxt] = 1; q.push(nxt); }
                }
            }
        }
        return jumps;
    }
};

