from typing import List
from collections import deque
class Solution:
    def jump(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0
        visited = [False] * n
        visited[0] = True
        q = deque([0])
        jumps = 0
        while q:
            jumps += 1
            for _ in range(len(q)):
                cur = q.popleft()
                reach = min(n - 1, cur + nums[cur])
                for nxt in range(cur + 1, reach + 1):
                    if nxt == n - 1:
                        return jumps
                    if not visited[nxt]:
                        visited[nxt] = True
                        q.append(nxt)
        return jumps

