class Solution {
    public int jump(int[] nums) {
        int n = nums.length;
        if (n == 1) return 0;
        boolean[] vis = new boolean[n];
        vis[0] = true;
        java.util.Queue<Integer> q = new java.util.ArrayDeque<>();
        q.offer(0);
        int jumps = 0;
        while (!q.isEmpty()) {
            jumps++;
            int sz = q.size();
            for (int k = 0; k < sz; k++) {
                int cur = q.poll();
                int reach = Math.min(n - 1, cur + nums[cur]);
                for (int nxt = cur + 1; nxt <= reach; nxt++) {
                    if (nxt == n - 1) return jumps;
                    if (!vis[nxt]) { vis[nxt] = true; q.offer(nxt); }
                }
            }
        }
        return jumps;
    }
}

